1	package indexroom
2	
3	import (
4		"crypto/hmac"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/base64"
8		"encoding/binary"
9		"encoding/hex"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"strings"
14		"sync/atomic"
15	)
16	
17	// ErrInvalidArgument marks a rejected query: out-of-range heights or page
18	// size, a malformed cursor, a cursor issued by another index instance, or
19	// continuation conditions that differ from the first page. It never reports
20	// chain data problems; use errors.Is to tell it apart from ErrQueryChanged.
21	var ErrInvalidArgument = errors.New("indexroom: invalid query argument")
22	
23	// ErrQueryChanged marks a continuation whose pinned range no longer matches
24	// the first page: a block in the range was replaced (even under the same
25	// hash, and even if only its timestamp changed) or the chain was shortened
26	// below the pinned upper bound. No results are returned; the caller must
27	// restart from a first-page query.
28	var ErrQueryChanged = errors.New("indexroom: query data changed")
29	
30	// queryTxsHookLocked is a test-only rendezvous invoked once per QueryTxs
31	// call while index.mu is held: for a first page after the tip-bound height has
32	// been resolved (and non-empty ranges only), and for a continuation only after
33	// every pinned-range check has passed, so the call is committed to a
34	// successful page against the chain state in effect. It is nil in production;
35	// reorg regression tests park a query here to force a concurrent Reorg to wait
36	// (or park the Reorg and make the query wait), making the "one complete
37	// main-chain view per page" observation deterministic instead of relying on
38	// scheduling luck.
39	var queryTxsHookLocked func(from, to int64, continuation bool)
40	
41	const (
42		// DefaultPageSize is the page length when TxQuery.PageSize is zero.
43		DefaultPageSize = 100
44		// MaxPageSize is the largest accepted TxQuery.PageSize.
45		MaxPageSize = 1000
46	)
47	
48	// TxQuery describes a transaction lookup against the main chain.
49	type TxQuery struct {
50		// From and To bound the searched heights, both inclusive. A zero From
51		// starts at height 1. A zero To pins the chain tip seen by the first
52		// page; an explicit To above the tip is clamped to it. Explicit heights
53		// must be positive, and an explicit To must not be below From.
54		From int64
55		To   int64
56		// TxIDs restricts results to these identifiers, matched by exact string
57		// comparison; an empty slice disables the filter. Duplicates and order
58		// inside the slice are irrelevant.
59		TxIDs []string
60		// PageSize picks the page length, 1..MaxPageSize; zero means
61		// DefaultPageSize. It may change between pages of the same query.
62		PageSize int
63		// Cursor continues an earlier query; empty asks for the first page. On
64		// continuation the height range and TxIDs must equal the first page's.
65		Cursor string
66	}
67	
68	// TxHit is one transaction occurrence on the main chain. The same
69	// identifier appears once per occurrence, in different blocks or several
70	// times inside one block.
71	type TxHit struct {
72		Height    int64
73		BlockHash string
74		TxID      string
75		Position  int
76	}
77	
78	// TxPage is one page of query results together with statistics over the
79	// whole filtered range. Hits are ordered by height, then by position inside
80	// the block.
81	type TxPage struct {
82		Hits []TxHit
83		// TotalMatches counts every matching occurrence in the pinned range; it
84		// does not change between pages of the same query.
85		TotalMatches int64
86		// MatchedBlocks counts the blocks holding at least one match.
87		MatchedBlocks int64
88		// ToHeight is the upper bound pinned by the first page: the requested
89		// To clamped to the chain tip seen at that moment.
90		ToHeight int64
91		// NextCursor continues the query; empty means this is the last page.
92		NextCursor string
93	}
94	
95	// QueryTxs searches the main chain for transaction occurrences matching the
96	// query. Every call observes one complete chain state: concurrent Append or
97	// Reorg calls never leak into a page, and the returned records are copies
98	// the caller may freely mutate. The query itself never modifies the index.
99	//
100	// The first page (empty Cursor) pins the filtered range and returns a
101	// continuation cursor while more results remain. Continuations reuse the
102	// pinned range — blocks appended above it are invisible to the query — and
103	// succeed as long as every block inside the range still matches the first
104	// page; otherwise they fail with ErrQueryChanged.
105	func (index *Index) QueryTxs(query TxQuery) (TxPage, error) {
106		pageSize, err := normalizePageSize(query.PageSize)
107		if err != nil {
108			return TxPage{}, err
109		}
110		if query.Cursor != "" {
111			return index.continueQuery(query, pageSize)
112		}
113		return index.firstQuery(query, pageSize)
114	}
115	
116	func normalizePageSize(size int) (int, error) {
117		if size == 0 {
118			return DefaultPageSize, nil
119		}
120		if size < 0 || size > MaxPageSize {
121			return 0, fmt.Errorf("%w: page size must be between 1 and %d", ErrInvalidArgument, MaxPageSize)
122		}
123		return size, nil
124	}
125	
126	// normalizeRange validates the requested heights and resolves the zero From
127	// default. A zero To is left as-is; it is resolved against the chain tip
128	// while holding the lock.
129	func normalizeRange(from, to int64) (int64, int64, error) {
130		if from < 0 {
131			return 0, 0, fmt.Errorf("%w: from height must be positive", ErrInvalidArgument)
132		}
133		if to < 0 {
134			return 0, 0, fmt.Errorf("%w: to height must be positive", ErrInvalidArgument)
135		}
136		if from == 0 {
137			from = 1
138		}
139		if to != 0 && to < from {
140			return 0, 0, fmt.Errorf("%w: to height is below from height", ErrInvalidArgument)
141		}
142		return from, to, nil
143	}
144	
145	func (index *Index) firstQuery(query TxQuery, pageSize int) (TxPage, error) {
146		from, to, err := normalizeRange(query.From, query.To)
147		if err != nil {
148			return TxPage{}, err
149		}
150	
151		index.mu.Lock()
152		defer index.mu.Unlock()
153	
154		if to == 0 || to > index.Tip {
155			to = index.Tip
156		}
157		page := TxPage{Hits: []TxHit{}, ToHeight: to}
158		if from > to {
159			// Empty index or a start above the tip: a successful empty result.
160			return page, nil
161		}
162		if queryTxsHookLocked != nil {
163			queryTxsHookLocked(from, to, false)
164		}
165		filter := newTxFilter(query.TxIDs)
166		hits, total, blocks := index.scanPageLocked(from, to, filter, 0, pageSize)
167		return index.buildPageLocked(query.To, filter, from, to, hits, total, blocks, 0, pageSize), nil
168	}
169	
170	func (index *Index) continueQuery(query TxQuery, pageSize int) (TxPage, error) {
171		payload, err := index.decodeCursor(query.Cursor)
172		if err != nil {
173			return TxPage{}, err
174		}
175		from, _, err := normalizeRange(query.From, query.To)
176		if err != nil {
177			return TxPage{}, err
178		}
179		if from != payload.From {
180			return TxPage{}, fmt.Errorf("%w: from height differs from the first page", ErrInvalidArgument)
181		}
182		if query.To != payload.ReqTo {
183			return TxPage{}, fmt.Errorf("%w: to height differs from the first page", ErrInvalidArgument)
184		}
185		// One canonicalization drives both set-equivalence and the rescanning
186		// filter; reordering or repeating identifiers changes nothing, while any
187		// added, removed, or replaced identifier rejects the continuation before
188		// the chain is examined.
189		filter := newTxFilter(query.TxIDs)
190		if filter.hexDigest() != payload.Set {
191			return TxPage{}, fmt.Errorf("%w: transaction filter differs from the first page", ErrInvalidArgument)
192		}
193	
194		index.mu.Lock()
195		defer index.mu.Unlock()
196	
197		if index.Tip < payload.To {
198			return TxPage{}, fmt.Errorf("%w: chain tip %d is below the pinned upper bound %d",
199				ErrQueryChanged, index.Tip, payload.To)
200		}
201		if got := hex.EncodeToString(index.fingerprintLocked(payload.From, payload.To)); got != payload.FP {
202			return TxPage{}, fmt.Errorf("%w: blocks in the pinned range differ from the first page", ErrQueryChanged)
203		}
204		if queryTxsHookLocked != nil {
205			queryTxsHookLocked(payload.From, payload.To, true)
206		}
207		// Re-scan the still-identical pinned range: the cursor records the
208		// absolute offset, but no full match list is kept between pages.
209		hits, total, blocks := index.scanPageLocked(payload.From, payload.To, filter, payload.Off, pageSize)
210		if payload.Off > total {
211			return TxPage{}, fmt.Errorf("%w: cursor offset is beyond the pinned results", ErrQueryChanged)
212		}
213		return index.buildPageLocked(query.To, filter, payload.From, payload.To, hits, total, blocks, payload.Off, pageSize), nil
214	}
215	
216	// buildPageLocked assembles one page from a page-sized scan and mints the
217	// continuation cursor when matches remain. total and blocks describe the
218	// whole pinned range; hits holds only the window [offset, offset+pageSize).
219	// reqTo is the caller's verbatim To (zero for tip-bound queries). The caller
220	// must hold index.mu.
221	func (index *Index) buildPageLocked(reqTo int64, filter txFilter, from, to int64, hits []TxHit, total, blocks, offset int64, pageSize int) TxPage {
222		page := TxPage{
223			Hits:          hits,
224			TotalMatches:  total,
225			MatchedBlocks: blocks,
226			ToHeight:      to,
227		}
228		if offset+int64(len(hits)) < total {
229			page.NextCursor = index.encodeCursor(cursorPayload{
230				V:     1,
231				From:  from,
232				ReqTo: reqTo,
233				To:    to,
234				Set:   filter.hexDigest(),
235				FP:    hex.EncodeToString(index.fingerprintLocked(from, to)),
236				Off:   offset + int64(len(hits)),
237			})
238		}
239		return page
240	}
241	
242	// scanPageLocked walks the whole pinned range once in height/position order,
243	// counting every matching occurrence and every block holding one, while
244	// retaining only the page window [offset, offset+pageSize) in a pre-sized
245	// slice: at most pageSize TxHit records, independent of how many matches the
246	// whole range holds. The caller must hold index.mu.
247	func (index *Index) scanPageLocked(from, to int64, filter txFilter, offset int64, pageSize int) (hits []TxHit, total, blocks int64) {
248		hits = make([]TxHit, 0, pageSize)
249		for height := from; height <= to; height++ {
250			block := index.Blocks[height]
251			matched := false
252			for position, tx := range block.Txs {
253				if !filter.matches(tx) {
254					continue
255				}
256				if total >= offset && int64(len(hits)) < int64(pageSize) {
257					hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
258				}
259				total++
260				matched = true
261			}
262			if matched {
263				blocks++
264			}
265		}
266		return hits, total, blocks
267	}
268	
269	// fingerprintLocked hashes the exact content of every block in [from, to]:
270	// height, hash, parent, the ordered transaction list, and the timestamp
271	// (distinguishing a missing timestamp from zero). The caller must hold
272	// index.mu.
273	func (index *Index) fingerprintLocked(from, to int64) []byte {
274		h := sha256.New()
275		var lenBuf [8]byte
276		writeString := func(s string) {
277			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(s)))
278			h.Write(lenBuf[:])
279			h.Write([]byte(s))
280		}
281		for height := from; height <= to; height++ {
282			block := index.Blocks[height]
283			binary.BigEndian.PutUint64(lenBuf[:], uint64(block.Height))
284			h.Write(lenBuf[:])
285			writeString(block.Hash)
286			writeString(block.Parent)
287			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(block.Txs)))
288			h.Write(lenBuf[:])
289			for _, tx := range block.Txs {
290				writeString(tx)
291			}
292			if block.Time == nil {
293				h.Write([]byte{0})
294			} else {
295				h.Write([]byte{1})
296				binary.BigEndian.PutUint64(lenBuf[:], uint64(*block.Time))
297				h.Write(lenBuf[:])
298			}
299		}
300		return h.Sum(nil)
301	}
302	
303	// cursorPayload is the signed state carried between pages of one query.
304	type cursorPayload struct {
305		V     int    `json:"v"`
306		From  int64  `json:"from"`
307		ReqTo int64  `json:"reqTo"`
308		To    int64  `json:"to"`
309		Set   string `json:"set"`
310		FP    string `json:"fp"`
311		Off   int64  `json:"off"`
312	}
313	
314	const cursorPrefix = "q1"
315	
316	// encodeCursor serializes the payload and signs it with the per-instance
317	// key, so cursors are self-contained yet unusable on any other index.
318	func (index *Index) encodeCursor(payload cursorPayload) string {
319		raw, err := json.Marshal(payload)
320		if err != nil {
321			panic(err) // cursorPayload only contains marshalable fields
322		}
323		body := base64.RawURLEncoding.EncodeToString(raw)
324		mac := hmac.New(sha256.New, index.key[:])
325		mac.Write([]byte(cursorPrefix + "." + body))
326		sig := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
327		return cursorPrefix + "." + body + "." + sig
328	}
329	
330	// decodeCursor verifies the signature before trusting any payload field;
331	// every failure is an argument error, never a data-changed error.
332	func (index *Index) decodeCursor(cursor string) (cursorPayload, error) {
333		var payload cursorPayload
334		parts := strings.Split(cursor, ".")
335		if len(parts) != 3 || parts[0] != cursorPrefix {
336			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
337		}
338		sig, err := base64.RawURLEncoding.DecodeString(parts[2])
339		if err != nil {
340			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
341		}
342		mac := hmac.New(sha256.New, index.key[:])
343		mac.Write([]byte(parts[0] + "." + parts[1]))
344		if !hmac.Equal(sig, mac.Sum(nil)) {
345			return payload, fmt.Errorf("%w: cursor not recognized by this index", ErrInvalidArgument)
346		}
347		raw, err := base64.RawURLEncoding.DecodeString(parts[1])
348		if err != nil {
349			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
350		}
351		if err := json.Unmarshal(raw, &payload); err != nil || payload.V != 1 {
352			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
353		}
354		return payload, nil
355	}
356	
357	var keyFallback atomic.Uint64
358	
359	// newKey derives the per-instance cursor signing key. crypto/rand is not
360	// expected to fail; the counter fallback still keeps keys unique per
361	// instance so cursors never validate across indexes.
362	func newKey() [32]byte {
363		var key [32]byte
364		if _, err := rand.Read(key[:]); err != nil {
365			binary.BigEndian.PutUint64(key[:8], keyFallback.Add(1))
366		}
367		return key
368	}
