1	package indexroom
2	
3	import (
4		"fmt"
5		"reflect"
6		"testing"
7	)
8	
9	// referenceScan independently computes the full filtered occurrence list and
10	// matched-block count for [from, to], the same way the old collectLocked did,
11	// so the page-sized scan can be compared against an oracle that keeps every
12	// record.
13	func referenceScan(index *Index, from, to int64, txIDs []string) ([]TxHit, int64) {
14		filter := map[string]struct{}{}
15		for _, id := range txIDs {
16			filter[id] = struct{}{}
17		}
18		var all []TxHit
19		var blocks int64
20		for height := from; height <= to; height++ {
21			block := index.Blocks[height]
22			matched := false
23			for position, tx := range block.Txs {
24				if len(txIDs) > 0 {
25					if _, ok := filter[tx]; !ok {
26						continue
27					}
28				}
29				all = append(all, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
30				matched = true
31			}
32			if matched {
33				blocks++
34			}
35		}
36		return all, blocks
37	}
38	
39	// TestScanPageLockedRetainsOnlyPageWindow is the memory contract behind the
40	// QueryTxs refactor: a scan may keep at most pageSize TxHit records no matter
41	// how many matches the pinned range holds, while totals still describe the
42	// whole range and every offset slices the same ordered occurrence list the
43	// old full-materialization scan would have produced.
44	func TestScanPageLockedRetainsOnlyPageWindow(t *testing.T) {
45		// 60 blocks, three txs each with repeated identifiers: 180 occurrences.
46		var blocks [][]string
47		for h := 0; h < 60; h++ {
48			blocks = append(blocks, []string{
49				fmt.Sprintf("t%d", h%5), // five ids cycling: selective filter
50				"keep",
51				"keep", // same id twice in one block: both occurrences survive
52			})
53		}
